package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(BigInteger)
 */
public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testWriteNumber_WithNonNullBigInteger() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(mapper);
        BigInteger value = new BigInteger("123456789012345678901234567890");

        // Act
        buffer.writeNumber(value);

        // Assert
        // We verify by serializing the buffer to a generator and checking the content
        // TokenBuffer stores tokens internally; we check if the token is VALUE_NUMBER_INT
        // and the value matches the expected string representation.
        JsonGenerator gen = buffer.asParser().getCodec().getFactory().createGenerator(new java.io.StringWriter());
        buffer.serialize(gen);
        gen.flush();

        // Since we can't easily access the internal _append state without reflection,
        // we use the parser to verify the content.
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(value, parser.getBigInteger());
    }

    @Test
    public void testWriteNumber_WithZero() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(mapper);
        BigInteger value = BigInteger.ZERO;

        // Act
        buffer.writeNumber(value);

        // Assert
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(value, parser.getBigInteger());
    }

    @Test
    public void testWriteNumber_WithNegativeBigInteger() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(mapper);
        BigInteger value = new BigInteger("-98765432109876543210");

        // Act
        buffer.writeNumber(value);

        // Assert
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        assertEquals(value, parser.getBigInteger());
    }

    @Test
    public void testWriteNumber_WithNull() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Act
        buffer.writeNumber(null);

        // Assert
        // When null is passed, it should call writeNull()
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.VALUE_NULL, parser.currentToken());
    }
}
